insert into public.products (slug,name,local_name,category,shape,palette,featured,tagline,description,origin,forms,variants,pack_sizes,moq,shelf_life,certifications,uses,sort_order) values
('ceylon-cinnamon','Ceylon Cinnamon','Kurundu','Bark & Quills','quill',array['#3b2216','#c47a3d'],true,'True cinnamon, hand-rolled quills with a sweet, delicate aroma.','Cinnamomum verum, the original ''true'' cinnamon grown along Sri Lanka''s south and west coasts. Inner bark is hand-peeled, layered and rolled into thin quills, then sun and shade dried. Graded by quill diameter, from the fine Alba to the robust Hamburg grades, plus quillings, featherings and powder for processors.','Galle, Matara and Kalutara districts',array['Whole','Cut','Ground'],'[{"name": "Alba", "note": "Finest grade, quill diameter under 6 mm"}, {"name": "C5 Special", "note": "Continental, 6 to 8 mm"}, {"name": "C5", "note": "Continental, around 8 to 10 mm"}, {"name": "C4", "note": "Continental, around 10 to 12 mm"}, {"name": "M5", "note": "Mexican grade, slightly thicker bark"}, {"name": "H1", "note": "Hamburg grade, thicker quills for grinding"}, {"name": "H2", "note": "Hamburg grade, economy"}, {"name": "Quillings", "note": "Broken pieces of quills"}, {"name": "Featherings", "note": "Inner bark shavings, ideal for extraction"}, {"name": "Powder", "note": "Ground from H grades and quillings"}]'::jsonb,array['500 g','1 kg','5 kg','25 kg carton'],'5 kg','24 months',array['SLS','Ceylon Cinnamon GI (on request)'],array['Retail packing','Bakeries & confectionery','Tea blends','Ayurveda & extraction'],10),
('black-pepper','Black Pepper','Gammiris','Whole Spices','seed',array['#1d1c18','#6b5a45'],true,'Bold, high-piperine Ceylon pepper from the central hills.','Sri Lankan black pepper is known for its high piperine content and sharp, lingering heat. Berries are picked at full maturity, sun dried and machine cleaned, then graded by bulk density. Available whole, crushed or ground.','Matale, Kandy and Kegalle districts',array['Whole','Crushed','Ground'],'[{"name": "550 g/L", "note": "Bold, high density"}, {"name": "500 g/L", "note": "Standard export quality"}, {"name": "Light berries", "note": "Economy, for grinding and oil"}, {"name": "Crushed", "note": "Coarse cracked pepper"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['500 g','1 kg','5 kg','25 kg bag','50 kg bag'],'10 kg','24 months',array['SLS'],array['Retail packing','Restaurants & hotels','Food manufacturing','Spice mixes'],20),
('white-pepper','White Pepper','Sudu Gammiris','Whole Spices','seed',array['#3a3326','#e6d8b8'],false,'Retted and decorticated pepper with a clean, earthy heat.','Ripe pepper berries are soaked to remove the outer skin, washed and dried to a pale cream colour. Milder in aroma than black pepper, it is preferred for white sauces, soups and processed foods where dark specks are not wanted.','Matale and Kandy districts',array['Whole','Ground'],'[{"name": "Whole", "note": "Clean, cream-coloured berries"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['500 g','1 kg','5 kg','25 kg bag'],'5 kg','24 months',array['SLS'],array['Food manufacturing','Restaurants & hotels','Sauces & soups'],30),
('cloves','Cloves','Karabu Neti','Whole Spices','clove',array['#2c1710','#9c4f2c'],true,'Hand-picked buds rich in eugenol and warm aroma.','Unopened flower buds of the clove tree, hand-picked and sun dried to a deep reddish brown. Sri Lankan cloves are prized for their high oil content and intense aroma. Supplied hand-picked, FAQ, as stems for distillation, or ground.','Kandy, Matale and Kegalle districts',array['Whole','Ground'],'[{"name": "Hand Picked Selected", "note": "Uniform, headed buds"}, {"name": "FAQ", "note": "Fair average quality"}, {"name": "Stems", "note": "For oil distillation"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','25 kg bag'],'5 kg','24 months',array['SLS'],array['Retail packing','Biryani & curry mixes','Bakeries','Oil distillation'],40),
('cardamom','Green Cardamom','Enasal','Whole Spices','pod',array['#1c2a16','#8fae4a'],true,'Bright green pods with a sweet, floral fragrance.','Grown under the forest canopy of Sri Lanka''s hill country, our cardamom pods are carefully dried to keep their green colour and aromatic seeds. Graded by pod size for retail and hotel buyers, with seeds and powder for processors.','Knuckles range, Kandy and Matale',array['Whole','Seeds','Ground'],'[{"name": "8 mm+", "note": "Extra bold pods"}, {"name": "7 to 8 mm", "note": "Bold pods"}, {"name": "6 to 7 mm", "note": "Medium pods"}, {"name": "Seeds", "note": "Decorticated seeds"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg'],'2 kg','18 months',array['SLS'],array['Tea & beverages','Sweets & desserts','Biryani','Retail packing'],50),
('nutmeg','Nutmeg','Sadikka','Whole Spices','nut',array['#2a1a12','#a8724a'],false,'Aromatic Ceylon nutmeg, in shell or shelled and sorted.','Seeds of the Myristica fragrans fruit, dried slowly in the shell and then cracked and sorted. Sri Lankan nutmeg has a rich, sweet aroma and high oil content.','Kandy and Matale districts',array['Whole','Ground'],'[{"name": "In shell", "note": "Whole nutmeg with shell"}, {"name": "Shelled, sound", "note": "Sorted, sound kernels"}, {"name": "BWP", "note": "Broken, for grinding and oil"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['500 g','1 kg','5 kg','25 kg bag'],'5 kg','24 months',array['SLS'],array['Bakeries','Meat processing','Spice mixes','Retail packing'],60),
('mace','Mace','Wasa Vasi','Whole Spices','blade',array['#3a1a10','#d0662e'],false,'The lacy red aril of nutmeg, delicate and fragrant.','Mace is the bright aril that wraps the nutmeg seed. It is peeled by hand and dried to an orange-red colour. Its flavour is finer and warmer than nutmeg, valued in curries, sausages and bakery.','Kandy and Matale districts',array['Whole','Ground'],'[{"name": "Whole blades", "note": "Unbroken, bright colour"}, {"name": "Broken", "note": "Pieces for grinding"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg'],'1 kg','18 months',array['SLS'],array['Biryani & curry mixes','Meat processing','Bakeries'],70),
('turmeric','Turmeric','Kaha','Roots & Rhizomes','finger',array['#3a2408','#e0a020'],true,'Golden, high-curcumin turmeric, as fingers or powder.','Turmeric rhizomes are boiled, sun dried and polished into hard golden fingers, then ground fresh to order. Deep colour, earthy aroma and no added colouring.','Kurunegala and Anuradhapura districts',array['Whole','Ground'],'[{"name": "Fingers", "note": "Dried and polished"}, {"name": "Bulbs", "note": "Round mother rhizomes"}, {"name": "Powder", "note": "Pure, no added colour"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg','25 kg bag'],'10 kg','18 months',array['SLS'],array['Retail packing','Curry mixes','Restaurants & hotels','Ayurveda'],80),
('dried-ginger','Dried Ginger','Viyali Inguru','Roots & Rhizomes','finger',array['#2e2414','#c9a46a'],false,'Pungent sun-dried ginger, sliced or ground.','Mature ginger rhizomes are peeled, sliced and sun dried, keeping their sharp, warming pungency. Used in beverages, herbal products and spice blends.','Kurunegala and Kandy districts',array['Whole','Sliced','Ground'],'[{"name": "Whole dried", "note": "Peeled rhizomes"}, {"name": "Slices", "note": "Sun-dried slices"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','25 kg bag'],'5 kg','18 months',array['SLS'],array['Tea & beverages','Ayurveda','Spice mixes'],90),
('dried-red-chilli','Dried Red Chilli','Viyali Miris','Chilli','chilli',array['#2e0e0a','#c0301e'],true,'Sun-dried whole chillies with deep colour and real heat.','Selected red chillies, sun dried and cleaned, supplied whole with or without stems, or as flakes. Bright colour and steady heat for curries, sambols and chilli pastes.','Puttalam, Kurunegala and imported origins',array['Whole','Flakes'],'[{"name": "With stem", "note": "Whole, stem on"}, {"name": "Stemless", "note": "Whole, stems removed"}, {"name": "Flakes", "note": "Crushed chilli pieces"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','10 kg bag','25 kg bag'],'10 kg','12 months',array['SLS'],array['Retail packing','Restaurants & hotels','Sambol & paste makers'],100),
('chilli-powder','Chilli Powder','Miris Kudu','Ground Spices','powder',array['#2e0e0a','#d8452a'],false,'Freshly ground chilli powder in hot and extra hot blends.','Ground from cleaned dried chillies with no added colour or fillers. Available in standard and extra hot blends, and as a coarse ''chilli pieces'' grind for Sri Lankan cooking.','Ground and packed in Galgamuwa',array['Ground'],'[{"name": "Standard", "note": "Medium heat, bright colour"}, {"name": "Extra hot", "note": "High heat blend"}, {"name": "Coarse pieces", "note": "Kochchi style coarse grind"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg','25 kg bag'],'10 kg','12 months',array['SLS'],array['Retail packing','Restaurants & hotels','Food manufacturing'],110),
('roasted-curry-powder','Roasted Curry Powder','Badapu Thuna Paha','Spice Blends','powder',array['#24140a','#8a4a22'],true,'Dark roasted Sri Lankan curry powder for meat and fish.','A traditional Sri Lankan blend of coriander, cumin, fennel, cinnamon, cardamom, cloves, curry leaves and pepper, slow roasted until dark and aromatic. Made in small batches and packed fresh.','Blended and packed in Galgamuwa',array['Ground'],'[{"name": "Meat curry", "note": "Dark roast"}, {"name": "Fish curry", "note": "Medium roast"}, {"name": "Custom blend", "note": "Your recipe, made to order"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg'],'10 kg','12 months',array['SLS'],array['Retail packing','Restaurants & hotels','Private label'],120),
('unroasted-curry-powder','Unroasted Curry Powder','Amu Thuna Paha','Spice Blends','powder',array['#2a200c','#b98a3a'],false,'Light, fragrant curry powder for vegetable curries.','The same balanced Sri Lankan spice blend, ground without roasting for a lighter colour and fresher flavour. Ideal for vegetable, dhal and coconut milk curries.','Blended and packed in Galgamuwa',array['Ground'],'[{"name": "Standard", "note": "Classic blend"}, {"name": "Custom blend", "note": "Your recipe, made to order"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg'],'10 kg','12 months',array['SLS'],array['Retail packing','Restaurants & hotels','Private label'],130),
('coriander-seeds','Coriander Seeds','Koththamalli','Seeds','seed',array['#2a2414','#b8a060'],false,'Clean, aromatic coriander for curries and herbal drinks.','Machine cleaned and sorted coriander seeds, supplied whole or ground. A base for Sri Lankan curry powders and the popular koththamalli herbal drink.','Imported and cleaned in Sri Lanka',array['Whole','Ground'],'[{"name": "Whole", "note": "Cleaned and sorted"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','25 kg bag'],'10 kg','18 months',array['SLS'],array['Curry mixes','Herbal drinks','Retail packing'],140),
('cumin-seeds','Cumin Seeds','Suduru','Seeds','grain',array['#2a2014','#a88454'],false,'Bold cumin with a warm, nutty aroma.','Cleaned and sorted cumin seeds for tempering, curry blends and food manufacturing. Supplied whole or freshly ground.','Imported and cleaned in Sri Lanka',array['Whole','Ground'],'[{"name": "Whole", "note": "Machine cleaned"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg','25 kg bag'],'5 kg','18 months',array['SLS'],array['Curry mixes','Restaurants & hotels','Retail packing'],150),
('fennel-seeds','Fennel Seeds','Maduru','Seeds','grain',array['#1e2614','#9aae62'],false,'Sweet, green fennel for blends and after-meal mixes.','Green, sweet-scented fennel seeds, cleaned and sorted. A key note in Sri Lankan curry powders and a favourite mouth freshener.','Imported and cleaned in Sri Lanka',array['Whole','Ground'],'[{"name": "Whole", "note": "Green, cleaned"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','25 kg bag'],'5 kg','18 months',array['SLS'],array['Curry mixes','Confectionery','Retail packing'],160),
('goraka','Goraka','Garcinia cambogia','Souring Agents','blade',array['#1a1410','#5a4030'],false,'Smoke-dried garcinia, the classic souring agent for fish curry.','Segments of the Garcinia cambogia fruit, dried and smoked until black. Essential for Sri Lankan ambul thiyal and fish curries, and in demand by nutraceutical processors.','Kurunegala, Kegalle and Ratnapura districts',array['Whole','Paste'],'[{"name": "Dried segments", "note": "Smoke dried, cleaned"}, {"name": "Paste", "note": "Ready to use"}]'::jsonb,array['250 g','500 g','1 kg','5 kg','25 kg bag'],'5 kg','24 months',array['SLS'],array['Restaurants & hotels','Retail packing','Extraction'],170),
('curry-leaves','Dried Curry Leaves','Karapincha','Herbs & Leaves','leaf',array['#121e10','#4f8a34'],false,'Shade-dried curry leaves that keep their colour and aroma.','Fresh curry leaves are shade dried to hold their green colour and fragrance. Supplied whole or as powder for spice mixes and instant foods.','Kurunegala district',array['Whole','Ground'],'[{"name": "Whole leaves", "note": "Shade dried"}, {"name": "Powder", "note": "Fine ground"}]'::jsonb,array['100 g','250 g','500 g','1 kg','5 kg'],'2 kg','12 months',array['SLS'],array['Spice mixes','Instant foods','Retail packing'],180)
